}

function setGroupOpacity(group, opacity) {
  group.traverse((o) => {
    if (o.material) {
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      mats.forEach((m) => {
        m.transparent = opacity < 0.999;
        m.opacity = opacity;
        m.depthWrite = opacity > 0.35;
      });
    }
  });
}

function makeArrow(origin, dir, length, color, headLength = 0.12, headWidth = 0.065) {
  const dvec = dir.clone().normalize();
  const start = origin.clone().addScaledVector(dvec, -length * 0.5);
  const a = new THREE.ArrowHelper(dvec, start, length, color, headLength, headWidth);
  a.traverse((o) => {
    if (o.material) {
      o.material = o.material.clone();
      o.material.transparent = true;
      o.material.opacity = 1;
    }
  });
  return a;
}

function makeTorusAt(pos, normal, radius, tubeRadius, color, opacity = 1) {
  const geom = new THREE.TorusGeometry(radius, tubeRadius, 18, 96);
