const xs = [-1.65, -0.55, 0.55, 1.65];
const ys = [-1.65, -0.55, 0.55, 1.65];
const zs = [-1.35, -0.25, 0.85, 1.75];
xs.forEach((x, ix) => ys.forEach((y, iy) => zs.forEach((z, iz) => {
  if ((ix + iy + iz) % 3 === 0 && z > 1.2) return;
  const p = mathToWorld(x + (iz % 2) * 0.08, y + (ix % 2) * 0.08, z);
  const a = makeArrow(p, FworldAtMath(x, y, z), 0.42, 0xf05a24, 0.13, 0.075);
  fieldGroup.add(a);
})));

function curveFrame(t, angle) {
  const center = tubeCurve.getPoint(t);
  const tangent = tubeCurve.getTangent(t).normalize();
  let n1 = new THREE.Vector3(0, 1, 0).cross(tangent);
  if (n1.lengthSq() < 0.001) n1 = new THREE.Vector3(1, 0, 0).cross(tangent);
  n1.normalize();
  const n2 = tangent.clone().cross(n1).normalize();
  const radial = n1.multiplyScalar(Math.cos(angle)).add(n2.multiplyScalar(Math.sin(angle))).normalize();
  return { center, tangent, radial, point: center.clone().addScaledVector(radial, 0.37) };
}

for (let i = 0; i < 18; i++) {
