}

function applyState() {
  const curlOn = state.vectorOverlay === 'curl F with dS';
  const boundaryOn = state.stokesFocus === 'Boundary C';

  activateButton('overlayField', !curlOn);
  activateButton('overlayCurl', curlOn);
  activateButton('focusSurface', !boundaryOn);
  activateButton('focusBoundary', boundaryOn);

  targets.field = curlOn ? 0.15 : 1.0;
  targets.curl = curlOn ? 1.0 : 0.0;
  targets.normals = curlOn ? 1.0 : 0.0;
  targets.tube = boundaryOn ? 0.35 : 0.92;
  targets.outline = boundaryOn ? 0.14 : 0.34;
  targets.wash = boundaryOn ? 0.02 : 0.14;
  targets.glow = boundaryOn ? 0.95 : 0.0;

  cRim.material.color.set(boundaryOn ? 0xffd34d : 0x12376f);
  cRim.scale.setScalar(boundaryOn ? 1.075 : 1.0);
  labelC.div.style.fontWeight = boundaryOn ? '700' : '400';
  labelC.div.style.color = boundaryOn ? '#000' : '#111';
  labelS.div.style.opacity = boundaryOn ? '0.55' : '1';
}

function setVectorOverlay(value) {
