  },
  {
    title: 'Replace S by its boundary',
    narration: 'The full blue surface fades and the front circular boundary C is highlighted. Stokes’ theorem says the difficult surface integral equals circulation around this boundary curve.',
    state: { vectorOverlay: 'curl F with dS', stokesFocus: 'Boundary C' }
  }
];

window.goToStep = function goToStep(i) {
  const step = steps[Math.max(0, Math.min(steps.length - 1, i | 0))];
  state.vectorOverlay = step.state.vectorOverlay;
  state.stokesFocus = step.state.stokesFocus;
  const n = document.getElementById('stepNarration');
  if (n) n.innerHTML = `<b>${step.title}</b><br>${step.narration}`;
