function lerp(a, b, t) { return a + (b - a) * t; }
function visualTransitionLoop() {
  requestAnimationFrame(visualTransitionLoop);
  setGroupOpacity(fieldGroup, lerp(fieldGroup.userData.opacity ?? 1, targets.field, 0.12));
  fieldGroup.userData.opacity = fieldGroup.children[0]?.children?.[0]?.material?.opacity ?? targets.field;

  setGroupOpacity(curlGroup, lerp(curlGroup.userData.opacity ?? 0, targets.curl, 0.12));
  curlGroup.userData.opacity = curlGroup.children[0]?.children?.[0]?.material?.opacity ?? targets.curl;

