function setObjectOpacity(obj, opacity) {
  obj.traverse((o) => {
    if (!o.material) return;
    const mats = Array.isArray(o.material) ? o.material : [o.material];
    mats.forEach((m) => {
      m.transparent = opacity < 0.999;
      m.opacity = opacity;
      m.depthWrite = opacity > 0.35;
    });
  });
}

function makeArrow(origin, dir, length, color, headLength = 0.12, headWidth = 0.07) {
  const dvec = dir.clone().normalize();
  const start = origin.clone().addScaledVector(dvec, -length * 0.5);
  const arrow = new THREE.ArrowHelper(dvec, start, length, color, headLength, headWidth);
  arrow.traverse((o) => {
    if (o.material) {
      o.material = o.material.clone();
      o.material.transparent = true;
      o.material.opacity = 1;
      o.material.depthWrite = true;
    }
  });
  return arrow;
}

function makeTubeCurve(points, radius, color, opacity = 1, tubularSegments = 180) {
  const curve = new THREE.CatmullRomCurve3(points, true, 'centripetal', 0.45);
  const geom = new THREE.TubeGeometry(curve, tubularSegments, radius, 10, true);
  const mat = new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    depthWrite: opacity > 0.35
  });
  const mesh = new THREE.Mesh(geom, mat);
  scene.add(mesh);
  return mesh;
}

