function outerEdge(t) {
  const x = 1.18 * Math.cos(t) + 0.34 * Math.cos(2 * t + 0.65) - 0.05;
  const y = 1.05 * Math.sin(t) + 0.68 * Math.cos(t - 0.65);
  const z = -0.08 + 0.32 * Math.sin(2 * t - 0.45) + 0.18 * Math.cos(t + 1.35);
