}

function sheetPoint(s, t) {
  const c = innerC(t);
  const o = outerEdge(t);
  const p = c.clone().lerp(o, s);
  const q = s * (1 - s);
  p.x += 0.12 * q * Math.cos(4 * t + 0.4);
  p.y += 0.23 * q * Math.sin(2 * t - 0.9);
  p.z += 0.40 * q * Math.sin(3 * t + 0.7);
  return p;
}

