function approximateNormal(s, t) {
  const epsS = 0.008;
  const epsT = 0.012;
  const pS1 = sheetWorldPoint(Math.min(1, s + epsS), t);
  const pS0 = sheetWorldPoint(Math.max(0, s - epsS), t);
  const pT1 = sheetWorldPoint(s, t + epsT);
  const pT0 = sheetWorldPoint(s, t - epsT);
  return pS1.sub(pS0).cross(pT1.sub(pT0)).normalize();
}

