  p.z += 0.86 * q * Math.sin(t + 0.65) + 0.34 * q * Math.sin(3 * t - 0.85);

  const leftLift = Math.exp(-Math.pow(THREE.MathUtils.euclideanModulo(t - 2.76 + Math.PI, 2 * Math.PI) - Math.PI, 2) / 0.48);
  const rightDip = Math.exp(-Math.pow(THREE.MathUtils.euclideanModulo(t - 5.26 + Math.PI, 2 * Math.PI) - Math.PI, 2) / 0.55);
  p.z += 0.32 * q * leftLift - 0.28 * q * rightDip;

  return p;
}

